import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson, putJson } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheetBody';
import { GRADES, peopleKey, usePeople } from './people';
import type { Grade, Person } from './people';

type Fields = { name: string; grade: Grade };
const EMPTY: Fields = { name: '', grade: 'A' };

// The people on the sheet: a form that adds a person, or edits the one whose editor is open, and
// the list of everyone in the order they were added.
function People({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const people = usePeople(sheetId);
  const [fields, setFields] = useState<Fields>(EMPTY);
  const [editing, setEditing] = useState<string | null>(null);
  const [error, setError] = useState('');

  const reset = () => {
    setFields(EMPTY);
    setEditing(null);
    setError('');
  };

  const save = useMutation({
    mutationFn: ({ id, body }: { id: string | null; body: Fields }) => {
      const base = `/api/sheets/${encodeURIComponent(sheetId)}/people`;
      return id === null
        ? postJson<Person>(base, body)
        : putJson<Person>(`${base}/${encodeURIComponent(id)}`, body);
    },
    onSuccess: () => {
      reset();
      void queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
    onError: (e) =>
      setError(
        e instanceof HttpError && e.status === 409
          ? 'That name is already in use.'
          : 'That person could not be saved.',
      ),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    if (fields.name.trim() === '') {
      setError('A name is required.');
      return;
    }
    save.mutate({ id: editing, body: fields });
  };

  const change = (next: Partial<Fields>) => {
    setFields((f) => ({ ...f, ...next }));
    setError('');
  };

  const open = (p: Person) => {
    setEditing(p.id);
    setFields({ name: p.name, grade: p.grade });
    setError('');
  };

  return (
    <section data-testid="people">
      <h2>People</h2>
      <form onSubmit={submit} data-testid="person-form">
        <label>
          Name{' '}
          <input
            data-testid="person-form-name"
            value={fields.name}
            onChange={(e) => change({ name: e.target.value })}
          />
        </label>{' '}
        <label>
          Grade{' '}
          <select
            data-testid="person-form-grade"
            value={fields.grade}
            onChange={(e) => change({ grade: e.target.value as Grade })}
          >
            {GRADES.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
          {editing === null ? 'Add' : 'Save'}
        </button>
        {editing !== null && (
          <>
            {' '}
            <button type="button" data-testid="person-form-cancel" onClick={reset}>
              Cancel
            </button>
          </>
        )}
        {error && (
          <p role="alert" data-testid="person-form-error">
            {error}
          </p>
        )}
      </form>
      {people.isError && (
        <p role="alert" data-testid="people-error">
          The people could not be read.
        </p>
      )}
      <table data-testid="people-list">
        <thead>
          <tr>
            <th>Name</th>
            <th>Grade</th>
            <th />
          </tr>
        </thead>
        <tbody>
          {(people.data ?? []).map((p) => (
            <tr key={p.id} data-testid={`person-row-${p.id}`}>
              <td data-testid="person-name">{p.name}</td>
              <td data-testid="person-grade">{p.grade}</td>
              <td>
                <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => open(p)}>
                  Edit
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 0, Component: People });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: Grade[] = ['A', 'B', 'C'];

export type Person = { id: string; name: string; grade: Grade };

export const peopleKey = (sheetId: string) => ['sheet', sheetId, 'people'] as const;

/** The sheet's people, in the order they were added. */
export function usePeople(sheetId: string) {
  return useQuery({
    queryKey: peopleKey(sheetId),
    queryFn: async () =>
      (await getJson<{ people: Person[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/people`)).people,
  });
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

export type Sheet = { id: string; today: string };

export const sheetKey = (sheetId: string) => ['sheet', sheetId, 'info'] as const;

/** The loaded sheet: its id and its today (yyyy-MM-dd). */
export function useSheet(sheetId: string) {
  return useQuery({
    queryKey: sheetKey(sheetId),
    queryFn: () => getJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}`),
  });
}

/**
 * The sheet's today. Every date-dependent decision and every default date on the screen uses this,
 * never the real clock (`new Date()`); '' until the sheet has been read.
 */
export function useSheetToday(sheetId: string): string {
  return useSheet(sheetId).data?.today ?? '';
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheetBody';
import { sheetKey, useSheet } from './sheet';
import type { Sheet } from './sheet';

// The sheet's today: shown, and changeable. A change re-reads everything kept for the sheet, as
// whatever depends on the date may now read differently.
function SheetToday({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const sheet = useSheet(sheetId);
  const [input, setInput] = useState('');
  const [error, setError] = useState('');

  const save = useMutation({
    mutationFn: (today: string) =>
      postJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}/today`, { today }),
    onSuccess: (updated) => {
      queryClient.setQueryData(sheetKey(sheetId), updated);
      void queryClient.invalidateQueries({
        queryKey: ['sheet', sheetId],
        predicate: (q) => q.queryKey[2] !== 'info',
      });
    },
    onError: () => setError('That date could not be set as today.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const today = input.trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(today)) {
      setError('Choose a date for today.');
      return;
    }
    save.mutate(today);
  };

  return (
    <form onSubmit={submit} data-testid="sheet-today-form">
      Today: <strong data-testid="sheet-today">{sheet.data?.today ?? ''}</strong>{' '}
      <label>
        Set today{' '}
        <input
          type="date"
          data-testid="sheet-today-input"
          value={input}
          onChange={(e) => {
            setInput(e.target.value);
            setError('');
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="sheet-today-save" disabled={save.isPending}>
        Set
      </button>
      {(error || sheet.isError) && (
        <p role="alert" data-testid="sheet-error">
          {error || 'The sheet could not be read.'}
        </p>
      )}
    </form>
  );
}

export const contribution = SheetBody.fill({ order: -100, Component: SheetToday });
import { defineSlot } from '../Slot';

/**
 * The shell's nav bar. Every page contributes its own link — the shell never lists the pages.
 * A nav link carries `data-testid="nav-<section>"` (the test contract; CLAUDE.md).
 */
export const AppNav = defineSlot('app.nav');
import { defineSlot } from '../Slot';

/**
 * The loaded sheet's body on the home screen. Everything kept per sheet (its people, claims,
 * settings) contributes here; it renders only once a user is signed in and a sheet is loaded, and
 * is remounted whenever a sheet is (re-)loaded, so a contribution starts from a fresh read.
 * Server data for a sheet lives under the query key ['sheet', sheetId, ...].
 */
export const SheetBody = defineSlot<{ sheetId: string; user: string }>('sheet.body');
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
// A non-2xx response, carrying its status so a caller can tell one refusal from another.
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

